head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > onFocusClass]<br/>SearchBox 컴포넌트에 포커스가 들어왔을 때 적용할 CSS 클래스명을 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 문자열로 설정할 수 있어야 합니다.",
        "값을 설정하지 않으면 Input 영역에 'w2input_focus' 클래스가 적용됩니다.",
        "속성값을 설정하면 기본값인 'w2input_focus' 클래스는 적용되지 않습니다.",
        "공백으로 구분된 다중 클래스명을 설정하면 포커스 시 모든 클래스가 함께 적용되어야 합니다.",
        "존재하지 않는 클래스명을 설정하더라도 SearchBox 의 Input 영역 className 속성에는 해당 클래스명이 추가되어야 합니다.",
        "컴포넌트가 포커스를 잃으면 적용된 CSS 클래스가 제거됩니다.",
        "readOnly=true 인 경우 포커스 이벤트가 발생하지 않으므로 onFocusClass 가 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        onFocusClass : con_onFocusClass.getText(),
        readOnly : con_readOnly.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicSearchBox(cList, 'ev:onfocus="scwin.target1_onfocus" ev:onblur="scwin.target1_onblur"');
}



// 포커스 인 핸들러 - 포커스 시 적용되는 className 출력
scwin.target1_onfocus = function (e) {
    let elem = target1.input.render;
    wf_body_bottom.getObj("scwin").setReturnValue("[onfocus] input className : " + elem.className);
};



// 포커스 아웃 핸들러 - 포커스 해제 시 className 출력 (클래스 제거 확인)
scwin.target1_onblur = function (e) {
    let elem = target1.input.render;
    wf_body_bottom.getObj("scwin").setReturnValue("[onblur] input className : " + elem.className);
};



// 현재 SearchBox 내부 input 의 className 확인 버튼
scwin.btn_getClassName_onclick = function (e) {
    let elem = target1.input.render;
    wf_body_bottom.getObj("scwin").setReturnValue("input className : " + elem.className);
};
